// Linux: click-through ARGB popup with a PNG next to the cursor.
// SWELL paints its windows as RGB24, so the popup is a plain GDK window drawn with
// cairo. Both libraries are already loaded by REAPER's libSwell; they are looked up at
// runtime, so the plugin does not link against GTK. Without a compositor the
// transparent pixels show as black.

#include "platform/platform.h"
#include "reaper_plugin_functions.h"
#include "settings.h"

#include "overlay_images.h" // generated by CMake from src/res/*.png

#include <dlfcn.h>

#include <cstring>
#include <string>

// Minimal GDK 3 / cairo declarations (their ABI is frozen)
struct GdkScreen; struct GdkVisual; struct GdkWindow; struct GdkCursor;
struct cairo_t; struct cairo_surface_t; struct cairo_region_t;
typedef int GdkFilterReturn;
typedef GdkFilterReturn (*GdkFilterFunc)(void* xevent, void* event, void* data);
typedef int cairo_status_t;
typedef cairo_status_t (*cairo_read_func_t)(void* closure, unsigned char* data, unsigned int length);

struct GdkWindowAttr
{
    char* title;
    int event_mask;
    int x, y;
    int width;
    int height;
    int wclass;
    GdkVisual* visual;
    int window_type;
    GdkCursor* cursor;
    char* wmclass_name;
    char* wmclass_class;
    int override_redirect;
    int type_hint;
};
enum
{
    GDK_EXPOSURE_MASK = 1 << 1,
    GDK_INPUT_OUTPUT = 0,
    GDK_WINDOW_TEMP = 3, // override-redirect
    GDK_WA_X = 1 << 2,
    GDK_WA_Y = 1 << 3,
    GDK_WA_VISUAL = 1 << 5,
    GDK_WA_TYPE_HINT = 1 << 8,
    GDK_WINDOW_TYPE_HINT_DND = 13,
    GDK_FILTER_CONTINUE = 0,
    X11_EXPOSE = 12,
    CAIRO_STATUS_SUCCESS = 0,
    CAIRO_STATUS_READ_ERROR = 10,
    CAIRO_OPERATOR_SOURCE = 1,
};

static struct
{
    GdkScreen* (*gdk_screen_get_default)();
    GdkVisual* (*gdk_screen_get_rgba_visual)(GdkScreen*);
    GdkWindow* (*gdk_window_new)(GdkWindow*, GdkWindowAttr*, int);
    void (*gdk_window_destroy)(GdkWindow*);
    void (*gdk_window_show_unraised)(GdkWindow*);
    void (*gdk_window_hide)(GdkWindow*);
    void (*gdk_window_move_resize)(GdkWindow*, int, int, int, int);
    void (*gdk_window_input_shape_combine_region)(GdkWindow*, const cairo_region_t*, int, int);
    void (*gdk_window_add_filter)(GdkWindow*, GdkFilterFunc, void*);
    void (*gdk_window_remove_filter)(GdkWindow*, GdkFilterFunc, void*);
    cairo_t* (*gdk_cairo_create)(GdkWindow*);
    void (*gdk_flush)();

    cairo_surface_t* (*cairo_image_surface_create_from_png)(const char*);
    cairo_surface_t* (*cairo_image_surface_create_from_png_stream)(cairo_read_func_t, void*);
    int (*cairo_image_surface_get_width)(cairo_surface_t*);
    int (*cairo_image_surface_get_height)(cairo_surface_t*);
    cairo_status_t (*cairo_surface_status)(cairo_surface_t*);
    void (*cairo_surface_destroy)(cairo_surface_t*);
    void (*cairo_set_operator)(cairo_t*, int);
    void (*cairo_set_source_surface)(cairo_t*, cairo_surface_t*, double, double);
    void (*cairo_paint)(cairo_t*);
    void (*cairo_destroy)(cairo_t*);
    cairo_region_t* (*cairo_region_create)();
    void (*cairo_region_destroy)(cairo_region_t*);
} G;

static bool LoadGdk()
{
    // Already loaded by libSwell: never load a second copy
    void* gdk = dlopen("libgdk-3.so.0", RTLD_LAZY | RTLD_NOLOAD);
    void* cairo = dlopen("libcairo.so.2", RTLD_LAZY | RTLD_NOLOAD);
    if (!gdk || !cairo) return false;

    bool ok = true;
    auto get = [&](void* lib, const char* name, auto& fn) {
        *(void**)&fn = dlsym(lib, name);
        if (!fn) ok = false;
    };
#define GDK_FN(name) get(gdk, #name, G.name)
#define CAIRO_FN(name) get(cairo, #name, G.name)
    GDK_FN(gdk_screen_get_default);
    GDK_FN(gdk_screen_get_rgba_visual);
    GDK_FN(gdk_window_new);
    GDK_FN(gdk_window_destroy);
    GDK_FN(gdk_window_show_unraised);
    GDK_FN(gdk_window_hide);
    GDK_FN(gdk_window_move_resize);
    GDK_FN(gdk_window_input_shape_combine_region);
    GDK_FN(gdk_window_add_filter);
    GDK_FN(gdk_window_remove_filter);
    GDK_FN(gdk_cairo_create);
    GDK_FN(gdk_flush);
    CAIRO_FN(cairo_image_surface_create_from_png);
    CAIRO_FN(cairo_image_surface_create_from_png_stream);
    CAIRO_FN(cairo_image_surface_get_width);
    CAIRO_FN(cairo_image_surface_get_height);
    CAIRO_FN(cairo_surface_status);
    CAIRO_FN(cairo_surface_destroy);
    CAIRO_FN(cairo_set_operator);
    CAIRO_FN(cairo_set_source_surface);
    CAIRO_FN(cairo_paint);
    CAIRO_FN(cairo_destroy);
    CAIRO_FN(cairo_region_create);
    CAIRO_FN(cairo_region_destroy);
#undef GDK_FN
#undef CAIRO_FN
    dlclose(gdk); // drops only the reference taken above
    dlclose(cairo);
    return ok;
}

struct PngStream
{
    const unsigned char* data;
    size_t size;
    size_t pos;
};

static cairo_status_t ReadPngStream(void* closure, unsigned char* out, unsigned int length)
{
    PngStream* s = (PngStream*)closure;
    if (s->size - s->pos < length) return CAIRO_STATUS_READ_ERROR;
    memcpy(out, s->data + s->pos, length);
    s->pos += length;
    return CAIRO_STATUS_SUCCESS;
}

static cairo_surface_t* CheckedSurface(cairo_surface_t* surface)
{
    if (surface && G.cairo_surface_status(surface) != CAIRO_STATUS_SUCCESS)
    {
        G.cairo_surface_destroy(surface);
        return nullptr;
    }
    return surface;
}

// Optional PNG in UserPlugins overrides the embedded default
static cairo_surface_t* LoadOverlayImage(const char* fileName, const unsigned char* data, size_t size)
{
    const char* source = "embedded";
    cairo_surface_t* image = nullptr;
    if (GetResourcePath)
    {
        std::string path = std::string(GetResourcePath()) + "/UserPlugins/" + fileName;
        if (platform::FileExists(path.c_str()))
        {
            image = CheckedSurface(G.cairo_image_surface_create_from_png(path.c_str()));
            if (image) source = "file";
        }
    }
    if (!image)
    {
        PngStream stream = { data, size, 0 };
        image = CheckedSurface(G.cairo_image_surface_create_from_png_stream(ReadPngStream, &stream));
    }
    DebugLog("[Drop To Sampler] overlay %s=%s (%s %dx%d)\n", fileName, image ? "OK" : "FAIL", source,
        image ? G.cairo_image_surface_get_width(image) : 0, image ? G.cairo_image_surface_get_height(image) : 0);
    return image;
}

// GDK may not be loaded yet when the plugin starts: everything is set up on first use
class GdkOverlay : public DragOverlay
{
public:
    ~GdkOverlay() override
    {
        if (m_window)
        {
            G.gdk_window_remove_filter(m_window, OnXEvent, this);
            G.gdk_window_destroy(m_window);
        }
        if (m_insert) G.cairo_surface_destroy(m_insert);
        if (m_replace) G.cairo_surface_destroy(m_replace);
    }

    void ShowAtCursor(DropVisualKind kind) override
    {
        if (!Init()) return;
        cairo_surface_t* image = (kind == DropVisual_Replace && m_replace) ? m_replace : m_insert;
        if (!image || !EnsureWindow())
        {
            Hide();
            return;
        }
        m_image = image;

        // Below-right of the cursor, like on Windows
        POINT pt = {};
        GetCursorPos(&pt);
        G.gdk_window_move_resize(m_window, pt.x + 16, pt.y + 16,
            G.cairo_image_surface_get_width(image), G.cairo_image_surface_get_height(image));
        if (!m_visible)
        {
            G.gdk_window_show_unraised(m_window);
            m_visible = true;
        }
        Paint();
        G.gdk_flush();
    }

    void Hide() override
    {
        if (m_window && m_visible)
        {
            G.gdk_window_hide(m_window);
            G.gdk_flush();
        }
        m_visible = false;
    }

private:
    bool Init()
    {
        if (!m_initDone)
        {
            m_initDone = true;
            m_gdk = LoadGdk();
            if (m_gdk)
            {
                m_insert = LoadOverlayImage("sampler_insert.png", k_sampler_insert_png, sizeof(k_sampler_insert_png));
                m_replace = LoadOverlayImage("sampler_replace.png", k_sampler_replace_png, sizeof(k_sampler_replace_png));
            }
            else
            {
                DebugLog("[Drop To Sampler] GDK 3 / cairo not loaded, no cursor overlay\n");
            }
        }
        return m_gdk;
    }

    bool EnsureWindow()
    {
        if (m_window) return true;
        GdkScreen* screen = G.gdk_screen_get_default();
        if (!screen) return false;

        GdkWindowAttr attr = {};
        attr.event_mask = GDK_EXPOSURE_MASK;
        attr.width = attr.height = 1;
        attr.wclass = GDK_INPUT_OUTPUT;
        attr.window_type = GDK_WINDOW_TEMP;
        attr.type_hint = GDK_WINDOW_TYPE_HINT_DND;
        attr.visual = G.gdk_screen_get_rgba_visual(screen); // null without a compositor
        int mask = GDK_WA_X | GDK_WA_Y | GDK_WA_TYPE_HINT | (attr.visual ? GDK_WA_VISUAL : 0);
        m_window = G.gdk_window_new(nullptr, &attr, mask);
        if (!m_window) return false;

        // Click-through, and never the drop target under the cursor
        cairo_region_t* empty = G.cairo_region_create();
        G.gdk_window_input_shape_combine_region(m_window, empty, 0, 0);
        G.cairo_region_destroy(empty);

        // SWELL's GDK event handler ignores windows it does not own: repaint on raw Expose
        G.gdk_window_add_filter(m_window, OnXEvent, this);
        return true;
    }

    void Paint()
    {
        if (!m_window || !m_visible || !m_image) return;
        cairo_t* cr = G.gdk_cairo_create(m_window);
        if (!cr) return;
        G.cairo_set_operator(cr, CAIRO_OPERATOR_SOURCE); // replace, keeping the PNG's alpha
        G.cairo_set_source_surface(cr, m_image, 0, 0);
        G.cairo_paint(cr);
        G.cairo_destroy(cr);
    }

    static GdkFilterReturn OnXEvent(void* xevent, void*, void* data)
    {
        if (xevent && *(int*)xevent == X11_EXPOSE) // XEvent.type
            ((GdkOverlay*)data)->Paint();
        return GDK_FILTER_CONTINUE;
    }

    GdkWindow* m_window = nullptr;
    cairo_surface_t* m_insert = nullptr;
    cairo_surface_t* m_replace = nullptr;
    cairo_surface_t* m_image = nullptr;
    bool m_visible = false;
    bool m_initDone = false;
    bool m_gdk = false;
};

std::unique_ptr<DragOverlay> DragOverlay::Create()
{
    return std::unique_ptr<DragOverlay>(new GdkOverlay());
}
